contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address operator, address from, uint256 tokenId, bytes calldata data) public {
        bytes4 ret = c.onERC721Received(operator, from, tokenId, data);
        assert(ret == bytes4(0x150b7a02));
    }

    receive() external payable {}
}

